  ('bearing-testimony', 'principle', 'Bearing Testimony', 'The duty and privilege of witnesses of God''s truth to declare boldly what they know to be true through the Spirit, inviting others to faith.', '{"category":"gospel-principle"}'::jsonb, 'anthropic-batch', 'phase-b', '''bear'':1A ''bold'':15B ''declar'':14B ''duti'':4B ''faith'':28B ''god'':10B ''invit'':25B ''know'':18B ''other'':26B ''privileg'':6B ''spirit'':24B ''testimoni'':2A ''true'':21B ''truth'':12B ''wit'':8B'::tsvector),
  ('charity', 'principle', 'Charity', 'The pure love of Christ; the highest virtue, enduring beyond all else, expressing itself in patient kindness, humility, and seeking the good of others.', '{"category":"christlike-attribute"}'::jsonb, 'anthropic-batch', 'phase-b', '''beyond'':11B ''chariti'':1A ''christ'':6B ''els'':13B ''endur'':10B ''express'':14B ''good'':23B ''highest'':8B ''humil'':19B ''kind'':18B ''love'':4B ''other'':25B ''patient'':17B ''pure'':3B ''seek'':21B ''virtu'':9B'::tsvector),
  ('dc-4', 'chapter', 'Doctrine and Covenants 4', NULL, '{"book_id":"dc","deprecated":true,"verse_count":7,"chapter_number":4}'::jsonb, 'lds-doc-project', 'canon', '''4'':4A ''coven'':3A ''doctrin'':1A'::tsvector),
  ('diligence', 'principle', 'Diligence', 'Persistent, earnest effort in fulfilling duties and developing talents, contrasted with sloth and half-hearted commitment.', '{"category":"christlike-attribute"}'::jsonb, 'anthropic-batch', 'phase-b', '''commit'':18B ''contrast'':11B ''develop'':9B ''dilig'':1A ''duti'':7B ''earnest'':3B ''effort'':4B ''fulfil'':6B ''half'':16B ''half-heart'':15B ''heart'':17B ''persist'':2B ''sloth'':13B ''talent'':10B'::tsvector),
  ('discernment', 'principle', 'Spiritual Discernment', 'The gift to distinguish between truth and error, good and evil, and the promptings of the Spirit versus the temptations of the adversary.', '{"category":"gospel-principle"}'::jsonb, 'anthropic-batch', 'phase-b', '''adversari'':25B ''discern'':2A ''distinguish'':6B ''error'':10B ''evil'':13B ''gift'':4B ''good'':11B ''prompt'':16B ''spirit'':19B ''spiritu'':1A ''temptat'':22B ''truth'':8B ''versus'':20B'::tsvector),
  ('divine-creation', 'principle', 'Divine Creation', 'God created all things including heaven, earth, and all life by the power of his word and according to his divine purposes.', '{"category":"doctrine"}'::jsonb, 'anthropic-batch', 'phase-b', '''accord'':20B ''creat'':4B ''creation'':2A ''divin'':1A,23B ''earth'':9B ''god'':3B ''heaven'':8B ''includ'':7B ''life'':12B ''power'':15B ''purpos'':24B ''thing'':6B ''word'':18B'::tsvector),
  ('divine-protection', 'principle', 'Divine Protection', 'God''s promised shelter and defense over those who trust and obey him, delivering them from enemies and temporal destruction.', '{"category":"gospel-principle"}'::jsonb, 'anthropic-batch', 'phase-b', '''defens'':8B ''deliv'':16B ''destruct'':22B ''divin'':1A ''enemi'':19B ''god'':3B ''obey'':14B ''promis'':5B ''protect'':2A ''shelter'':6B ''tempor'':21B ''trust'':12B'::tsvector),
  ('dominion-over-creation', 'symbol', 'Dominion Over Creation', 'Christ''s kingship over all creation (Psalm 8; Hebrews 2:6–8), and the saints'' co-reign with Christ in the millennial and eternal kingdom', '{"type_name":"Vicegerency and royal priesthood","confidence":"strong","textual_anchor":"let them have dominion over the fish of the sea, and over the fowl of the air, and over the cattle, and over all the earth","scholarly_consensus":"consensus"}'::jsonb, 'anthropic-batch', 'phase-b', '''2'':13B ''6'':14B ''8'':11B,15B ''christ'':4B,23B ''co'':20B ''co-reign'':19B ''creation'':3A,9B ''dominion'':1A ''etern'':28B ''hebrew'':12B ''kingdom'':29B ''kingship'':6B ''millenni'':26B ''psalm'':10B ''reign'':21B ''saint'':18B'::tsvector),
  ('earth', 'place', 'Earth', 'The physical world, referenced in contrast to heaven when discussing the binding and loosing authority given to disciples.', '{"geography":"The terrestrial world as a whole.","place_type":"land"}'::jsonb, 'anthropic-batch', 'phase-b', '''author'':16B ''bind'':13B ''contrast'':7B ''discipl'':19B ''discuss'':11B ''earth'':1A ''given'':17B ''heaven'':9B ''loos'':15B ''physic'':3B ''referenc'':5B ''world'':4B'::tsvector),
  ('endure-to-end', 'principle', 'Endure to the End', 'The requirement to maintain faithfulness and covenant commitment throughout one''s mortal life in order to inherit salvation.', '{"category":"gospel-principle"}'::jsonb, 'anthropic-batch', 'phase-b', '''commit'':12B ''coven'':11B ''end'':4A ''endur'':1A ''faith'':9B ''inherit'':21B ''life'':17B ''maintain'':8B ''mortal'':16B ''one'':14B ''order'':19B ''requir'':6B ''salvat'':22B ''throughout'':13B'::tsvector),
  ('enos', 'book', 'Enos', 'The Book of Enos', '{"abbrev":"Enos","long_name":"The Book of Enos","volume_id":"bom","deprecated":true,"sort_order":70,"chapter_count":1}'::jsonb, 'lds-doc-project', 'canon', '''book'':3B ''eno'':1A,5B'::tsvector),
  ('eternal-life', 'principle', 'Eternal Life', 'The quality and kind of life possessed by God, granted to the faithful as the greatest of all divine gifts, consisting of immortality and exaltation in God''s presence.', '{"category":"doctrine"}'::jsonb, 'anthropic-batch', 'phase-b', '''consist'':23B ''divin'':21B ''etern'':1A ''exalt'':27B ''faith'':15B ''gift'':22B ''god'':11B,29B ''grant'':12B ''greatest'':18B ''immort'':25B ''kind'':6B ''life'':2A,8B ''possess'':9B ''presenc'':31B ''qualiti'':4B'::tsvector),
